package com.doms.doms.service;
import com.doms.doms.entity.*;import com.doms.doms.exception.QuotaExceededException;import com.doms.doms.repository.MonthlyUploadUsageRepository;import org.junit.jupiter.api.Test;import java.time.LocalDate;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class QuotaServiceTest{
 @Test void exactLimitSucceedsAndNextByteFails(){MonthlyUploadUsageRepository repo=mock(MonthlyUploadUsageRepository.class);Plan plan=Plan.builder().name("Silver").slug("silver").active(true).monthlyUploadLimitBytes(5L*1024*1024*1024).build();User user=User.builder().plan(plan).subscriptionStartDate(LocalDate.now().minusDays(1)).subscriptionEndDate(LocalDate.now().plusYears(1)).build();MonthlyUploadUsage row=MonthlyUploadUsage.builder().user(user).periodStart(LocalDate.now().minusDays(1)).periodEnd(LocalDate.now().plusDays(29)).usedBytes(plan.getMonthlyUploadLimitBytes()-1).build();when(repo.findForUpdate(eq(user),any())).thenReturn(Optional.of(row));when(repo.save(any())).thenAnswer(i->i.getArgument(0));QuotaService service=new QuotaService(repo);service.reserve(user,1);assertEquals(plan.getMonthlyUploadLimitBytes(),row.getUsedBytes());assertThrows(QuotaExceededException.class,()->service.reserve(user,1));}
 @Test void inactiveAndExpiredSubscriptionsAreRejected(){MonthlyUploadUsageRepository repo=mock(MonthlyUploadUsageRepository.class);User user=User.builder().plan(Plan.builder().name("Silver").active(false).build()).subscriptionStartDate(LocalDate.now().minusMonths(2)).subscriptionEndDate(LocalDate.now().minusDays(1)).build();assertThrows(IllegalArgumentException.class,()->new QuotaService(repo).reserve(user,10));}
 @Test void binaryPlanLimitsAreExact(){assertEquals(5_368_709_120L,5L*1024*1024*1024);assertEquals(8_589_934_592L,8L*1024*1024*1024);assertEquals(16_106_127_360L,15L*1024*1024*1024);}
}
